int twoSumsolve(vector<int> ans,  int target, int index, long sum) {
    int l = index;
    int r = ans.size() - 1;
    // 记录成立的搭配方案
    int res = 0;
    while (l < r) {
        long tmp = sum  + ans[l] + ans[r];
        if (tmp < target) {
            l++;
        } else if (tmp > target) {
            r--;
        } else {
            res++;
            // 去重
            while (l + 1 < r && ans[l] == ans[l+1]) {
                l++;
            }
            // 去重
            while (r - 1 > l && ans[r] == ans[r-1]) {
                r--;
            }
            l++;
            r--;            
        }
    }
    return res;
}
