int  solve(vector<int> ans, int k , int target, int index, long sum) {
    int res = 0;
    // 直接使用两数之和判断
    if (k == 2) {
        return twoSumsolve(ans, target, index, sum);
    }
​
    for (int i = index; i <= ans.size() - k; i++) {
        // 剪枝
        if (ans[i] > 0 && sum + ans[i] > target) {
            break;
        }
        // 防止重复
        if (i > index && ans[i] == ans[i-1]) {
            continue;
        }
        res += solve(ans, k  - 1, target, i + 1, sum + ans[i]);
    }
    return res;
}
