def two_sum_solve(nums, target, index, total):
    # 两数之和：双指针处理
    l, r = index, len(nums) - 1
    res = 0
    while l < r:
        tmp = total + nums[l] + nums[r]
        if tmp < target:
            l += 1
        elif tmp > target:
            r -= 1
        else:
            res += 1
            # 去重
            left, right = nums[l], nums[r]
            while l < r and nums[l] == left:
                l += 1
            while l < r and nums[r] == right:
                r -= 1
    return res
​
def solve(nums, k, target, index, total):
    if k == 2:
        return two_sum_solve(nums, target, index, total)
    res = 0
    for i in range(index, len(nums) - k + 1):
        # 剪枝
        if nums[i] > 0 and total + nums[i] > target:
            break
        # 跳过重复
        if i > index and nums[i] == nums[i - 1]:
            continue
        res += solve(nums, k - 1, target, i + 1, total + nums[i])
    return res
