package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
// twoSumSolve 实现两数之和的逻辑，使用双指针并去重
func twoSumSolve(nums []int, target int, index int, sum int) int {
    left := index
    right := len(nums) - 1
    count := 0
​
    for left < right {
        total := sum + nums[left] + nums[right]
        if total < target {
            left++
        } else if total > target {
            right--
        } else {
            count++
            // 去重处理
            lv := nums[left]
            rv := nums[right]
            for left < right && nums[left] == lv {
                left++
            }
            for left < right && nums[right] == rv {
                right--
            }
        }
    }
​
    return count
}
​
// solve 实现 k 数之和的递归逻辑
func solve(nums []int, k int, target int, index int, sum int) int {
    if k == 2 {
        return twoSumSolve(nums, target, index, sum)
    }
​
    count := 0
    for i := index; i <= len(nums)-k; i++ {
        // 剪枝：如果当前数加上 sum 已经超过目标，后续不可能满足
        if i > index && nums[i] == nums[i-1] {
            continue // 去重
        }
        // 进一步剪枝优化（因为数组已排序）
        if nums[i] > 0 && sum+nums[i] > target {
            break
        }
        count += solve(nums, k-1, target, i+1, sum+nums[i])
    }
    return count
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取第一行：一行空格分隔的整数
    scanner.Scan()
    line := scanner.Text()
    parts := strings.Fields(line)
​
    nums := make([]int, 0, len(parts))
    for _, s := range parts {
        num, _ := strconv.Atoi(s)
        nums = append(nums, num)
    }
​
    // 读取第二行：k
    scanner.Scan()
    k, _ := strconv.Atoi(scanner.Text())
​
    // 读取第三行：target
    scanner.Scan()
    target, _ := strconv.Atoi(scanner.Text())
​
    if len(nums) < k {
        fmt.Println(0)
        return
    }
​
    sort.Ints(nums)
    result := solve(nums, k, target, 0, 0)
    fmt.Println(result)
}
